<?php
declare(strict_types=1);
session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Strict','use_strict_mode'=>true]);
header('X-Content-Type-Options: nosniff');header('Referrer-Policy: same-origin');header('Cache-Control: no-store');
require 'db.php';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$s=trim((string)($_GET['search']??''));$total=(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn();
if($s!==''){$q=$pdo->prepare("SELECT roll_number,full_name,father_name,phone,department,program,semester,address FROM students WHERE full_name LIKE :n OR roll_number LIKE :r ORDER BY created_at DESC LIMIT 200");$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$s).'%';$q->execute([':n'=>$term,':r'=>$term]);$rows=$q->fetchAll();}
else $rows=$pdo->query('SELECT roll_number,full_name,father_name,phone,department,program,semester,address FROM students ORDER BY created_at DESC LIMIT 200')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Directory</title><link rel="stylesheet" href="style.css"><style>.directory{padding:35px 0}.directory h1{font:800 38px Manrope,sans-serif}.count{padding:14px;background:white;border:1px solid #e4e9f2;border-radius:10px}.count b{font:800 24px Manrope}.search{display:flex;gap:10px;margin:20px 0}.search input{flex:1;min-width:0;padding:13px;border:1px solid #dce3ed;border-radius:9px}table{width:100%;min-width:760px;border-collapse:collapse}th{text-align:left;background:#f4f6fb;color:#758198;padding:13px;font-size:10px}td{padding:13px;border-bottom:1px solid #edf0f6;font-size:12px;vertical-align:top}td small{display:block;margin-top:4px;color:#8591a5}.wrap{overflow:auto}.roll{color:#4e6ce0;font-weight:700}.empty{text-align:center;padding:35px;color:#758198}@media(max-width:620px){.search{flex-wrap:wrap}.search input{flex-basis:100%}.directory h1{font-size:30px}}</style></head><body><header class="nav"><a class="brand" href="index.html"><span class="logo">N<span>+</span></span><span><b>NFC STUDENT PORTAL</b><small>Registration & Records</small></span></a><nav><a href="index.html">Registration</a><a class="active" href="students.php">Student Directory ↗</a></nav></header><main class="shell directory"><div class="eyebrow dark">RECORDS MANAGEMENT</div><h1>Student Directory</h1><p style="color:#758198">Search students by full or partial name or roll number.</p><div class="count"><b><?php echo $total;?></b><br><small>Total saved records</small></div><section class="panel" style="margin-top:20px;padding:25px"><h2>Find A Student</h2><form class="search" method="get"><input name="search" maxlength="120" value="<?php echo e($s);?>" placeholder="Enter name or roll number"><button class="btn primary">Search ↗</button><a class="btn ghost" href="students.php">Reset</a></form><p style="font-size:12px;color:#758198"><?php echo count($rows);?> results (maximum 200 displayed)</p><div class="wrap"><table><thead><tr><th>Roll Number</th><th>Student</th><th>Department / Program</th><th>Semester</th><th>Phone</th><th>Address</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No matching students found.</td></tr><?php else:foreach($rows as $r):?><tr><td class="roll"><?php echo e($r['roll_number']);?></td><td><b><?php echo e($r['full_name']);?></b><small><?php echo e($r['father_name']);?></small></td><td><?php echo e($r['department']);?><small><?php echo e($r['program']);?></small></td><td><?php echo e($r['semester']);?></td><td><?php echo e($r['phone']);?></td><td><?php echo e($r['address']);?></td></tr><?php endforeach;endif;?></tbody></table></div><p style="font-size:11px;color:#758198">Local demo only. Add authentication before using real student information.</p></section></main></body></html>